import{z as o,x as l,o as e,c as s,q as t,j as i,D as E,d as B,s as A,S as n}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"过拟合的市场特有形态","description":"","frontmatter":{"title":"过拟合的市场特有形态","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/slm-overfitting-market.md","filePath":"quant/slm-overfitting-market.md","lastUpdated":1791063341000}'),d={name:"quant/slm-overfitting-market.md"};function p(m,a,f,h,D,u){const r=l("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="过拟合的市场特有形态" tabindex="-1">过拟合的市场特有形态 <a class="header-anchor" href="#过拟合的市场特有形态" aria-label="Permalink to &quot;过拟合的市场特有形态&quot;">​</a></h1><div class="epigraph"><p>市场上的过拟合大多不来自模型太复杂，而来自同一份历史被太多次使用；容量只是共犯，数据复用才是主犯。</p><footer>—— 据 Bailey, Borwein, López de Prado and Zhu, *Notices of the AMS*, 2014；McLean and Pontiff, *Journal of Finance*, 2016 整理</footer></div><p><a href="/quant/slm-nn-cross-section">上一课</a>把网络容量压到浅层仍有富余——因为真正的敌人不在模型内，在评估外。方法单元的三族模型任何一族都适用，也任何一族都能被同样的手法美化。本课进入纪律单元，先把「过拟合在市场上长什么样」分类；度量的数学（DSR、PBO、Reality Check）在<a href="/quant/backtest-overfitting">过拟合次数与试错</a>与<a href="/quant/overfit-as-risk">过拟合作为风险</a>已收，本课管形态与对位预防。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>教科书把过拟合绑定在模型容量上；市场的过拟合大多不来自容量，来自数据使用方式。于是会出现容量极小的模型「样本外」照样崩塌——因为它的样本外早已被无数次先前的尝试污染，而账本上一行都没记。不分类就预防不了：把选择类死法当成泄漏去修管道，修完了 \\(N\\) 还是被低估，极值门槛照样失守。缺口是一张形态学清单，每个形态配一个检测器。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三类形态，各配检测。泄漏类：特征用了未来信息、标签 horizon 重叠未清洗、幸存者与回填混进样本——检测靠点时数据（<a href="/quant/point-in-time">时点基本面</a>、<a href="/quant/look-ahead-bias">前视偏差</a>、<a href="/quant/survivorship-bias">幸存者偏差</a>）与 purge/embargo（<a href="/quant/fml-tscv-deep">时序交叉验证的深化</a>）。选择类：试验次数 \\(N\\) 不可见、冠军偏置、在滚动结果上再挑窗口——检测靠 \\(N\\) 台账与 DSR/PBO（<a href="/quant/bailey-dsr">Deflated Sharpe 原文</a>、<a href="/quant/pbo">Probability of Backtest Overfitting</a>）。环境类：对特定 regime 的过拟合与发表后衰减——McLean-Pontiff 的衰减是应写进原假设的预算，检测归<a href="/quant/live-drift-monitor">实盘漂移监测</a>。</p>',7)),(e(),i(n,null,{default:E(()=>[A(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E6%B3%84%E6%BC%8F%E7%B1%BB%EF%BC%9A%E6%9C%AA%E6%9D%A5%E4%BF%A1%E6%81%AF%E3%80%81%E9%87%8D%E5%8F%A0%E3%80%81%E5%B9%B8%E5%AD%98%E8%80%85%22%5D%20--%3E%20DL%5B%22%E7%82%B9%E6%97%B6%E5%BA%93%E4%B8%8E%20purge%E3%80%81embargo%22%5D%0A%20%20S%5B%22%E9%80%89%E6%8B%A9%E7%B1%BB%EF%BC%9AN%20%E6%AC%A1%E8%AF%95%E9%94%99%E3%80%81%E5%86%A0%E5%86%9B%E5%81%8F%E7%BD%AE%22%5D%20--%3E%20DS%5B%22N%20%E5%8F%B0%E8%B4%A6%E4%B8%8E%20DSR%E3%80%81PBO%22%5D%0A%20%20E%5B%22%E7%8E%AF%E5%A2%83%E7%B1%BB%EF%BC%9Aregime%20%E6%8B%9F%E5%90%88%E3%80%81%E6%8B%A5%E6%8C%A4%E8%A1%B0%E5%87%8F%22%5D%20--%3E%20DE%5B%22%E8%A1%B0%E5%87%8F%E9%A2%84%E7%AE%97%E4%B8%8E%E6%BC%82%E7%A7%BB%E7%9B%91%E6%B5%8B%22%5D%0A%20%20DL%20--%3E%20G%5B%22%E5%8D%8F%E8%AE%AE%EF%BC%9A%E7%AC%AC%206%20%E8%AF%BE%22%5D%0A%20%20DS%20--%3E%20G%0A%20%20DE%20--%3E%20G%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么市场比图像容易过拟合：有效样本是时间长度，截面相关让「股票数乘以天数」的名义样本虚胖；标签重叠让同一笔收益重复计数；信噪比千分位让任何拟合的方差项巨大。三个放大器相乘的结果是：不清洗的 \\(K\\) 折显著性可以虚高数倍，桌下几十次尝试就能把无技能簇推出一个「显著」冠军。过拟合也不是大模型的专利——重复使用同一份历史本身就是过拟合来源（Bailey 等 2014）：第 2 课的 \\(\\lambda\\)、第 3 课的深度、第 4 课的层数，每次尝试都是同一种行为，账必须记在同一本台账上。</p><p><span class="marginnote">标签 horizon 为 \\(H\\) 的逐日滚动持有，相邻 \\(H\\) 条标签共享同一笔收益，独立样本数近似从 \\(T\\) 缩到 \\(T/H\\)；不 purge 的交叉验证把标准误按约 \\(\\sqrt{H}\\) 倍低估，\\(H=20\\) 时 \\(t\\) 统计量虚高约四倍半——泄漏类死法里最便宜的一种，一行切分代码就能犯。</span></p><p><span class="marginnote">DSR（紧缩夏普率）就是把「这个策略是从 \\(N\\) 次尝试里挑出来的」折进显著性检验：试得越多，同样一份回测夏普越不值钱；PBO 则直接估计「样本内排名冠军在样本外翻车的概率」。两者都要以 \\(N\\) 台账为原料——台账漏记一次，它们就低估一次。</span></p><p><span class="marginnote">初学者容易以为「我只试了三五个模型，谈不上选择偏差」；实际上换一次特征、调一次窗口、删一天异常行情都算一次试验，而且常常没记进台账。桌面上三次尝试的下面，往往压着三十次没记的——这正是 \\(N\\) 被低估、极值门槛失守的主通道。</span></p>',5)),(e(),i(n,null,{default:E(()=>[A(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%90%8D%E4%B9%89%E6%A0%B7%E6%9C%AC%EF%BC%9A%E8%82%A1%E7%A5%A8%E6%95%B0%20%C3%97%20%E5%A4%A9%E6%95%B0%22%5D%20--%3E%20B%5B%22%E6%88%AA%E9%9D%A2%E7%9B%B8%E5%85%B3%EF%BC%9A%E5%90%8C%E4%B8%80%E8%A1%8C%E6%83%85%E4%BC%A0%E6%9F%93%E5%85%A8%E5%B8%82%E5%9C%BA%22%5D%0A%20%20A%20--%3E%20C%5B%22%E6%A0%87%E7%AD%BE%E9%87%8D%E5%8F%A0%EF%BC%9A%E7%9B%B8%E9%82%BB%E7%AA%97%E5%8F%A3%E5%85%B1%E4%BA%AB%E6%94%B6%E7%9B%8A%22%5D%0A%20%20A%20--%3E%20D%5B%22%E4%BF%A1%E5%99%AA%E6%AF%94%E5%8D%83%E5%88%86%E4%BD%8D%EF%BC%9A%E4%BF%A1%E5%8F%B7%E5%9F%8B%E5%9C%A8%E5%99%AA%E5%A3%B0%E9%87%8C%22%5D%0A%20%20B%20--%3E%20E%5B%22%E6%9C%89%E6%95%88%E6%A0%B7%E6%9C%AC%E8%BF%9C%E5%B0%8F%E4%BA%8E%E5%90%8D%E4%B9%89%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20C%20--%3E%20E%0A%20%20D%20--%3E%20E%0A%20%20E%20--%3E%20F%5B%22%E4%B8%8D%E6%B8%85%E6%B4%97%E7%9A%84%E6%98%BE%E8%91%97%E6%80%A7%E8%99%9A%E9%AB%98%E6%95%B0%E5%80%8D%22%5D%0A%20%20F%20--%3E%20G%5B%22%E6%A1%8C%E4%B8%8B%E5%87%A0%E5%8D%81%E6%AC%A1%E5%B0%9D%E8%AF%95%E6%8E%A8%E5%87%BA%E5%81%87%E5%86%A0%E5%86%9B%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>三类的边界不总清晰：拥挤衰减会被误诊为泄漏，regime 拟合会被误诊为概念漂移，分流次序按「先管道、再协变量、后概念」（<a href="/quant/fml-drift-management">漂移管理</a>）。</p><p><span class="marginnote">环境类过拟合可以想象成背题：模型把低利率年代里「哪种股票涨」的标准答案背得滚瓜烂熟，一旦利率环境反转，考卷换了，背熟的答案全部作废。它和泄漏、选择的区别在于——题目本身没抄错，是出题人换了题。</span>过拟合不能靠更好的模型修复，只能靠协议修复——虚假 alpha 通过仓位变成真实亏损（<a href="/quant/overfit-as-risk">过拟合作为风险</a>的杠杆账）。本课只给形态与检测器；把检测器排成时间表、规定「选择发生在哪、测试块何时动用」，是下一课样本外协议的事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>市场过拟合三形态：泄漏、选择、环境；修复必须对位，错诊比不诊更贵。</li><li>泄漏靠点时数据与 purge/embargo；选择靠 \\(N\\) 台账与 DSR/PBO；环境靠衰减预算与漂移监测。</li><li>标签重叠使有效样本近似 \\(T/H\\)，不清洗的显著性按 \\(\\sqrt{H}\\) 虚高。</li><li>数据复用与容量同罪：每次调参都是一次试验，记进同一本台账。</li><li>出处：Bailey, Borwein, López de Prado and Zhu, <em>Notices of the AMS</em>, 2014；McLean and Pontiff, <em>JF</em>, 2016；López de Prado, <em>Advances in Financial Machine Learning</em>, Wiley, 2018。</li></ul>',5))])}const _=o(d,[["render",p]]);export{c as __pageData,_ as default};
